05d1how.css:
display: inline-flex;
align-items: center;
gap: var(--space-xs);
min-block-size: 44px;
padding: 0;
border: 0;
background: none;
color: inherit;
font: inherit;
font-weight: 700;
cursor: pointer;
justify-self: start;
--btn-text-align: start; /* ACSS's button reset centres text via this variable; keep the label flush beside the play icon when it wraps */

& > span:first-child {
  display: grid;
  place-items: center;
  inline-size: 2.125rem;
  aspect-ratio: 1;
  flex: none;
  border-radius: 50%;
  background: var(--secondary);
  box-shadow: 0 6px 18px -6px color-mix(in oklch, var(--black) 40%, transparent);
  transition: transform 0.35s cubic-bezier(.34, 1.5, .64, 1);

  &::before {
    content: "";
    inline-size: 38%;
    aspect-ratio: 1;
    margin-inline-start: 8%;
    background: var(--base);
    clip-path: polygon(0 0, 100% 50%, 0 100%);
  }
}

&:hover > span:first-child {
  transform: scale(1.1);
}

&:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 3px;
  border-radius: var(--radius);
}

