2smw2vr.css:
padding-block: var(--space-m);
gap: var(--space-s); /* label above, marquee below */

& p {
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-dark-muted);
}

& ul {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-s) var(--space-l);
  list-style: none;
  padding: 0;
  margin: 0;
}

/* without the marquee (reduced motion) the list wraps inside the content column */
& > ul {
  inline-size: 100%;
  max-inline-size: var(--content-width);
}

/* the marquee runs the full screen width: it cancels the section's side padding */
& .marquee {
  flex: none;
  inline-size: calc(100% + 2 * var(--gutter));
}

& img {
  border-radius: 0; /* logos are never clipped by a rounded corner */
  inline-size: auto;
  max-block-size: 40px;
  max-inline-size: 150px;
}

/* bigger logos on desktop: they are the proof */
@media (width >= 48em) {
  & ul {
    gap: var(--space-s) var(--space-xl);
  }

  & img {
    max-block-size: 56px;
    max-inline-size: 220px;
  }
}

3671r4c.css:
& .section-head + form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 22rem), 1fr));
  gap: var(--space-xl);
  align-items: start;
}

& form > div {
  display: grid;
  gap: var(--space-l);
}

& fieldset {
  border: 0;
  margin: 0;
  padding: 0;
  display: grid;
  gap: var(--space-s);
  min-inline-size: 0;
}

& legend {
  display: flex;
  align-items: baseline;
  gap: var(--space-xs);
  padding: 0;
  margin-block-end: var(--space-s);
  font-weight: 700;
  font-size: var(--text-l);

  & span {
    font-size: var(--text-s);
    font-weight: 700;
    letter-spacing: 0.1em;
    color: var(--tertiary);
  }
}

& fieldset > div {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-xs);
}

& fieldset label {
  position: relative;

  & input {
    position: absolute;
    inset: 0;
    opacity: 0;
    margin: 0;
    cursor: pointer;
  }

  & span {
    display: inline-flex;
    align-items: center;
    min-block-size: 44px;
    padding-inline: 1.1em;
    border: 1.5px solid var(--border-color-light);
    border-radius: 999px;
    font-weight: 700;
    font-size: var(--text-s);
    color: var(--white);
    transition: background-color 0.2s, border-color 0.2s, color 0.2s;
  }

  &:hover span {
    border-color: var(--tertiary);
  }

  & input:checked + span {
    background-color: var(--secondary);
    border-color: var(--secondary);
    color: var(--base);
  }

  & input:focus-visible + span {
    outline: var(--focus-width) solid var(--tertiary);
    outline-offset: 2px;
  }
}

& form > div > div:last-child {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  gap: var(--space-s);

  & > label {
    display: grid;
    gap: var(--space-xs);
    font-weight: 600;
    font-size: var(--text-s);
    color: var(--text-light-muted);
  }

  & > label[data-wide] {
    grid-column: 1 / -1;
  }

  & > label[data-hp] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }

  & input,
  & textarea {
    font: inherit;
    font-size: var(--text-m);
    color: var(--white);
    background-color: color-mix(in oklch, var(--white) 6%, transparent);
    border: 1.5px solid var(--border-color-light);
    border-radius: var(--radius);
    padding: 0.8em 0.9em;
    min-block-size: 52px;

    &:focus {
      outline: none;
      border-color: var(--secondary);
    }

    &[aria-invalid='true'] {
      border-color: var(--accent);
    }
  }

  & textarea {
    min-block-size: 7rem;
    resize: vertical;
  }
}

& aside {
  position: sticky;
  inset-block-start: calc(var(--header-height) + var(--space-m));
  display: grid;
  gap: var(--space-s);
  padding: var(--space-l);
  border-radius: calc(var(--radius) * 1.375);
  background-color: var(--bg-light);
  color: var(--text-dark);

  & > div:first-child {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--space-xs);

    & small {
      font-size: var(--text-xs);
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--text-dark-muted);
    }
  }

  & [data-brief-steps] {
    display: flex;
    gap: 5px;
    flex: 1;
    max-inline-size: 120px;

    & i {
      flex: 1;
      block-size: 6px;
      border-radius: 3px;
      background-color: var(--neutral-ultra-light);
      transition: background-color 0.3s;
    }

    & i[data-on] {
      background-color: var(--primary);
    }
  }

  & > div:nth-child(2) {
    border: var(--border);
    border-radius: var(--radius);
    overflow: hidden;

    & > div:first-child {
      display: grid;
      gap: 2px;
      padding: var(--space-xs) var(--space-s);
      border-block-end: var(--border);
      font-size: var(--text-s);
      color: var(--text-dark-muted);

      & b {
        color: var(--text-dark);
      }
    }
  }

  & [data-brief-body] {
    display: grid;
    gap: var(--space-xs);
    align-content: start;
    min-block-size: 11rem;
    padding: var(--space-s);
    font-size: var(--text-s);
    line-height: 1.5;

    & ul {
      margin: 0;
      padding-inline-start: 1.2em;
    }

    & dl {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 0.2em 0.8em;
      margin: 0;
    }

    & dt {
      font-weight: 700;
    }

    & dd {
      margin: 0;
    }

    & [data-sig] {
      color: var(--text-dark-muted);
    }
  }

  & button[type='submit'] {
    inline-size: 100%;
    --btn-background: var(--primary);
    --btn-background-hover: var(--primary-hover);
    --btn-border-color: var(--primary);
    --btn-border-color-hover: var(--primary-hover);
    --btn-text-color: var(--white);
    --btn-text-color-hover: var(--white);
  }

  & [data-brief-status] {
    display: grid;
    gap: var(--space-xs);
    padding: var(--space-s);
    border-radius: var(--radius);
    background-color: var(--primary-ultra-light);
    font-size: var(--text-s);

    & b {
      color: var(--primary);
    }

    & a {
      color: inherit;
      font-weight: 800;
    }

    &[data-error] {
      background-color: var(--accent-ultra-light);

      & b {
        color: var(--accent);
      }
    }

    &[hidden] {
      display: none;
    }
  }

  & > a {
    font-weight: 800;
    color: var(--primary);
    text-decoration: none;
    min-block-size: 44px;
    display: inline-flex;
    align-items: center;

    &:hover {
      text-decoration: underline;
    }
  }

  & > p:last-child {
    display: grid;
    gap: 2px;
    font-size: var(--text-s);
    color: var(--text-dark-muted);

    & a {
      font-weight: 700;
      color: var(--text-dark);
      min-block-size: 44px;
      display: inline-flex;
      align-items: center;
    }
  }
}

& .section-head > p:last-child {
  font-weight: 600;
  color: var(--white);
}

4zgprr3.css:
margin: auto; /* native dialog centring (the CSS reset zeroes margins) */
inline-size: min(940px, calc(100vw - 20px));
max-block-size: calc(100dvh - 24px);
padding: 0;
border: 0;
border-radius: calc(var(--radius) * 1.5);
background-color: var(--bg-light);
color: var(--text-dark);
overflow: auto;
overscroll-behavior: contain;

&::backdrop {
  background: color-mix(in oklch, var(--base) 62%, transparent);
}

/* the close button and the content share one grid cell, so the button never narrows the content (a float did, leaving a gap on the right on phones) */
&[open] {
  display: grid;
  grid-template: "stack" auto / minmax(0, 1fr);
}

& [data-quiz-close] {
  grid-area: stack;
  justify-self: end;
  align-self: start;
  position: sticky;
  inset-block-start: 12px;
  z-index: 2;
  margin: 12px 12px 0 0;
}

& > div {
  grid-area: stack;
  min-inline-size: 0;
}

/* full screen on phones (mockup v117) */
@media (width <= 760px) {
  inline-size: 100vw;
  max-inline-size: 100vw;
  block-size: 100dvh;
  max-block-size: 100dvh;
  margin: 0;
  inset: 0;
  border-radius: 0;
}

& > div {
  display: grid;
  gap: var(--space-l);
  padding: clamp(26px, 4vw, 44px);
}

& [data-quiz-q] {
  display: grid;
  gap: var(--space-m);
  padding: var(--space-l);
  border: var(--border);
  border-radius: calc(var(--radius) * 1.375);
  background-color: var(--bg-ultra-light);

  & > div:first-child {
    display: grid;
    gap: var(--space-xs);

    & span {
      font-size: var(--text-xs);
      font-weight: 800;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--text-dark-muted);
    }
  }

  & [data-quiz-bar] {
    block-size: 6px;
    border-radius: 9px;
    background-color: var(--neutral-ultra-light);
    overflow: hidden;

    & i {
      display: block;
      block-size: 100%;
      inline-size: 20%;
      border-radius: 9px;
      background-color: var(--primary);
      transition: inline-size 0.4s ease;
    }
  }

  & fieldset {
    display: none;
    gap: var(--space-s);
    border: 0;
    margin: 0;
    padding: 0;

    &[data-on] {
      display: grid;
    }

    &:focus {
      outline: none;
    }

    & legend {
      display: flex;
      align-items: center;
      gap: var(--space-xs);
      margin-block-end: var(--space-s);
      padding: 0;
      font-weight: 800;
      font-size: var(--h4);
      line-height: 1.2;

      & span {
        display: grid;
        place-items: center;
        flex: none;
        inline-size: 28px;
        aspect-ratio: 1;
        border-radius: 50%;
        font-size: var(--text-xs);
        background-color: var(--base);
        color: var(--white);
      }
    }

    & legend + p {
      color: var(--text-dark-muted);
      font-size: var(--text-s);
    }
  }

  & [data-quiz-who] {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
    gap: var(--space-s);

    & label {
      display: grid;
      gap: var(--space-xs);
      font-weight: 700;
      font-size: var(--text-s);
    }

    & input {
      font: inherit;
      font-size: var(--text-m);
      font-weight: 500;
      min-block-size: 52px;
      padding: 0.75em 0.9em;
      border: 1.5px solid var(--neutral-ultra-light);
      border-radius: var(--radius);
      background-color: var(--bg-light);

      &:focus {
        outline: none;
        border-color: var(--primary);
        box-shadow: 0 0 0 3px var(--primary-ultra-light);
      }
    }
  }

  & [data-quiz-opts] {
    display: grid;
    gap: var(--space-xs);

    &[data-chips] {
      display: flex;
      flex-wrap: wrap;
    }

    & button {
      display: grid;
      gap: 3px;
      min-block-size: 44px;
      padding: 0.8em 1em;
      border: 1.5px solid var(--neutral-ultra-light);
      border-radius: var(--radius);
      background-color: var(--bg-light);
      text-align: start;
      font-weight: 700;
      font-size: var(--text-s);
      transition: border-color 0.3s, background-color 0.3s, color 0.3s;

      & small {
        font-weight: 500;
        color: var(--text-dark-muted);
      }

      &:hover {
        border-color: var(--primary);
      }

      &[aria-pressed='true'] {
        border-color: var(--primary);
        background-color: var(--primary-ultra-light);
      }
    }

    &[data-chips] button {
      border-radius: 999px;
      min-block-size: 36px;
      padding-block: 0.45em;

      &[aria-pressed='true'] {
        background-color: var(--primary);
        color: var(--white);
      }
    }
  }

  & [data-quiz-nav] {
    display: flex;
    justify-content: space-between;
    gap: var(--space-xs);
    padding-block-start: var(--space-s);
    border-block-start: var(--border);

    & button[disabled] {
      opacity: 0.4;
      pointer-events: none;
    }
  }
}

& [data-quiz-root][data-done] [data-quiz-q] {
  display: none;
}

& [data-quiz-root]:not([data-done]) [data-quiz-result] {
  display: none;
}

& [data-quiz-result] {
  padding: var(--space-l);
  border-radius: calc(var(--radius) * 1.375);
}

& [data-quiz-out] {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: var(--space-l) var(--space-xl);

  &[hidden] {
    display: none;
  }

  & > div:first-child,
  & > div:last-child {
    grid-column: 1 / -1;
  }

  & > div:first-child {
    display: grid;
    gap: var(--space-xs);

    & span {
      font-size: var(--text-xs);
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--tertiary);
    }

    & h3 {
      font-size: var(--h3);
      line-height: 1.05;
      color: var(--white);
    }
  }

  & small {
    display: block;
    margin-block-end: var(--space-xs);
    font-size: var(--text-xs);
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--ink-3);
  }

  & [data-quiz-list] {
    display: grid;
    gap: var(--space-xs);
    list-style: none;
    padding: 0;

    & li {
      display: grid;
      gap: 4px;
      padding: var(--space-s);
      border: var(--border-light);
      border-radius: var(--radius);
      background-color: color-mix(in oklch, var(--white) 5%, transparent);
    }

    & s {
      font-size: var(--text-s);
      color: var(--ink-3);
    }

    & b {
      color: var(--white);
    }

    & span {
      font-size: var(--text-s);
      color: var(--text-light-muted);
    }

    & [data-more] {
      border: 0;
      background: none;
      padding: 0;
      color: var(--text-light-muted);
    }
  }

  & [data-quiz-time] {
    display: grid;
    gap: 4px;
    padding: var(--space-m);
    border-radius: var(--radius);
    background-color: var(--secondary);
    color: var(--base);

    & small {
      color: var(--secondary-ultra-dark);
    }

    & b {
      font-size: var(--h3);
      line-height: 1.05;
    }
  }

  & [data-quiz-time] + div {
    margin-block-start: var(--space-m);

    & ul {
      display: grid;
      gap: var(--space-xs);
      list-style: none;
      padding: 0;
    }

    & li {
      position: relative;
      padding-inline-start: 1.6em;
      font-size: var(--text-s);
      color: var(--text-light-muted);

      &::before {
        content: "//";
        position: absolute;
        inset-inline-start: 0;
        font-weight: 800;
        color: var(--secondary);
      }
    }
  }

  & > div:last-child {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-xs);
    padding-block-start: var(--space-m);
    border-block-start: var(--border-light);

    & [data-quiz-again] {
      min-block-size: 44px;
      padding-inline: 0.5em;
      font-weight: 700;
      font-size: var(--text-s);
      color: var(--text-light-muted);
      text-decoration: underline;
    }
  }
}

@media (width < 40em) {
  inline-size: 100vw;
  max-inline-size: 100vw;
  block-size: 100dvh;
  max-block-size: 100dvh;
  margin: 0;
  border-radius: 0;

  & > div {
    padding: var(--space-xl) var(--gutter);
  }
}

@media (prefers-reduced-motion: reduce) {
  & [data-quiz-bar] i {
    transition: none;
  }
}


/* the result heading takes focus so screen readers announce it; it is not a control, so no focus ring */
& [tabindex="-1"]:focus {
  outline: none;
}

