81ycykl.css:
& > [data-etch-element="container"] {
  /* width queries below measure this box (screen width minus the side gutters), not the screen */
  container: sec / inline-size;
}

& .section-head ~ ol {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 12.5rem), 1fr));
  gap: var(--space-s);
  list-style: none;
  padding: 0;
  counter-reset: leak;

  & li {
    counter-increment: leak;
    display: grid;
    gap: var(--space-xs);
    align-content: start;
    padding: var(--space-s);
    border: var(--border);
    border-radius: calc(var(--radius) * 0.875);
    background-color: var(--bg-ultra-light);

    & p:first-child {
      display: flex;
      align-items: center;
      gap: var(--space-xs);
      font-size: var(--text-xs);
      font-weight: 700;
      color: var(--text-dark-muted);

      &::before {
        content: counter(leak);
        display: grid;
        place-items: center;
        flex: none;
        inline-size: 1.7em;
        aspect-ratio: 1;
        border-radius: 50%;
        background-color: var(--accent);
        color: var(--white);
      }
    }

    & p:nth-child(2) {
      font-size: var(--text-s);
    }

    & p:last-child {
      font-size: var(--text-s);
      color: var(--primary);
      font-weight: 600;
    }
  }
}

& ol + a {
  justify-self: start;
}

/* Interactive board (mounted by the section script; the list above is the no-JS version) */

& {
  background:var(--white);
  border-bottom:1px solid var(--neutral-ultra-light);
}

& .sm-top {
  display:flex;
  flex-wrap:wrap;
  justify-content:space-between;
  align-items:center;
  gap:14px 20px;
