display: grid;
grid-template-columns: auto 1fr;
align-items: center;
gap: var(--space-s);
inline-size: 100%;
max-inline-size: 26rem;
padding: var(--space-xs);
border: 1px solid color-mix(in oklch, currentColor 18%, transparent);
border-radius: var(--radius);
background: color-mix(in oklch, currentColor 6%, transparent);
color: inherit;
font: inherit;
text-align: start;
cursor: pointer;

& > span:first-child {
  position: relative;
  display: grid;
  place-items: center;
  inline-size: 7.5rem;
  border-radius: calc(var(--radius) * 0.75);
  overflow: hidden;

  & img {
    grid-area: 1 / 1;
    inline-size: 100%;
    aspect-ratio: 16 / 9;
    object-fit: cover;
    display: block;
  }

  & > span {
    grid-area: 1 / 1;
    display: grid;
  place-items: center;
  inline-size: 2.125rem;
  aspect-ratio: 1;
  flex: none;
  border-radius: 50%;
  background: var(--secondary);
  box-shadow: 0 6px 18px -6px color-mix(in oklch, var(--black) 40%, transparent);
  transition: transform 0.35s cubic-bezier(.34, 1.5, .64, 1);

  &::before {
    content: "";
    inline-size: 38%;
    aspect-ratio: 1;
    margin-inline-start: 8%;
    background: var(--base);
    clip-path: polygon(0 0, 100% 50%, 0 100%);
  }
  }
}

& > span:last-child {
  justify-self: start;
  text-align: start;
}

& b {
  display: block;
}

& small {
  opacity: 0.75;
}

&:hover > span:first-child > span {
  transform: scale(1.1);
}

&:focus-visible {
  outline: 3px solid var(--secondary);
  outline-offset: 3px;
}

bhyyw6v.css:
& .section-head + div {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 22rem), 1fr));
  gap: clamp(16px, 2.4vw, 28px);
}

/* card (mockup v117 .sols-card): preview on top, pillar tag over it, the whole card opens the window */
& article {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: clamp(18px, 2.2vw, 26px);
  border: 1px solid var(--neutral-ultra-light);
  border-radius: 24px;
  background-color: var(--bg-ultra-light);
  transition: transform 0.6s var(--ease), box-shadow 0.6s var(--ease), border-color 0.6s var(--ease);

  &:hover {
    transform: translateY(-4px);
    border-color: var(--base);
    box-shadow: 0 28px 50px -30px color-mix(in oklch, var(--base) 45%, transparent);
  }

  &:has(button:focus-visible) {
    outline: 3px solid var(--primary);
    outline-offset: 3px;
  }

  & .pillar-tag {
    position: absolute;
    inset-block-start: clamp(28px, 3.2vw, 38px);
    inset-inline-end: clamp(28px, 3.2vw, 38px);
    z-index: 1;
  }

  & h3 {
    font-size: clamp(1.7rem, 2.8vw, 2.4rem);
    font-weight: 800;
    letter-spacing: -0.03em;
    line-height: 0.95;
  }

  & p {
    color: var(--text-dark-muted);
    max-inline-size: 44ch;
    line-height: 1.5;
    text-wrap: pretty;
  }

  & button {
    margin-block-start: auto;
    padding: 8px 0 0;
    border: 0;
    background: none;
    font-weight: 800;
    color: var(--primary);
    text-align: start;
    cursor: pointer;

    &:focus-visible {
      outline: none;
    }

    /* stretch the click area over the whole card */
    &::after {
      content: "";
      position: absolute;
      inset: 0;
      border-radius: inherit;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }
}

/* app previews (mockup v117, CSS-only) */
& .sols-vis {
  display: block;
  position: relative;
  aspect-ratio: 16 / 10;
  border-radius: 16px;
  overflow: hidden;

  /* :where() keeps this default weak, so each preview part below can set its own display */
  & > :where(span),
  & :where(i, b) {
    display: block;
  }

  & > span {
    position: absolute;
    inset-inline: 12%;
  }

  &::before {
    content: "";
    position: absolute;
    inset: 12% 8% -6%;
    background: var(--white);
    border-radius: 14px;
    box-shadow: 0 20px 40px -20px color-mix(in oklch, var(--base) 50%, transparent);
    transition: transform 0.7s var(--ease);
  }
}

& article:hover .sols-vis::before {
  transform: translateY(-6px);
}

& .vv {
  background: var(--tertiary);
}

& .vr {
  background: var(--primary);
}

& .vv-bar {
  inset-block-start: 17%;
  display: flex;
  gap: 5px;

  & i {
    inline-size: 7px;
