dasf9uh.css:
background-color: var(--bg-ultra-dark);
color: var(--text-light-muted);
padding: 0 var(--gutter) var(--space-l);
font-size: var(--text-s);

& > div {
  inline-size: 100%;
  max-inline-size: var(--content-width);
  margin-inline: auto;
}

& a {
  color: inherit;
  text-decoration: none;

  &:hover {
    color: var(--white);
  }
}

/* CTA row: hidden on the home page, which ends in its own contact section */
& > div:first-of-type {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: var(--space-m);
  padding-block: var(--section-space-m) var(--space-xl);
  border-block-end: var(--border-light);

  :where(.home) & {
    display: none;
  }

  & > p {
    font-size: clamp(2rem, 4.6vw, 3.8rem);
    font-weight: 800;
    line-height: 1;
    letter-spacing: -0.035em;
    color: var(--white);
    max-inline-size: 13ch;
    text-wrap: balance;

    & span {
      color: var(--secondary);
    }
  }

  & > div {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-s);
  }

  & .btn--secondary:not(.btn--outline) {
    color: var(--base);
  }

  & .btn--outline {
    color: var(--white);
    border-color: color-mix(in oklch, var(--white) 45%, transparent);

    &:hover {
      color: var(--base);
    }
  }
}

/* Link grid */
& > div:nth-of-type(2) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr));
  gap: var(--space-l);
  padding-block: var(--space-xl);

  & > div {
    display: grid;
    gap: var(--space-s);
    align-content: start;
    grid-column: span 2;

    & > a:first-child {
      display: inline-flex;
      align-items: center;
      min-block-size: 44px;
    }

    & svg {
      block-size: 26px;
      inline-size: auto;
    }
  }

  & nav {
    display: grid;
    gap: var(--space-xs);
    align-content: start;

    & p {
      font-size: var(--text-xs);
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--white);
    }

    & a {
      display: inline-flex;
      align-items: center;
      min-block-size: 44px;
    }
  }
}

/* Bottom row */
& > div:last-of-type {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--space-xs) var(--space-m);
  padding-block-start: var(--space-m);
  border-block-start: var(--border-light);
  font-size: var(--text-xs);
}

/* ===== Mockup v117 parity: contact email bold white ===== */
& a[href^="mailto:"] {
  font-weight: 700;
  color: var(--white);
}

/* full width from the start: no rising-sheet handoff from the site motion script */
&.rise > .rise-fx {
  display: none;
}

