  stroke-width:12;
}

& .rx-ring .rx-arc {
  stroke:var(--t);
  stroke-dasharray:327;
  stroke-dashoffset:327;
  transition:stroke-dashoffset .7s var(--ease);
}

& .rx-ring b {
  grid-area:1/1;
