  & .rx-brand>span {
    font-size:.95rem;
  }

  & .rx-brand small {
    display:none;
  }

  & .rx-tools {
    margin-left:auto;
  }

  & .rx-exit {
    padding:9px 12px;
  }

  & .rx-sits {
    gap:8px;
  }

  & .rx-sit {
    padding:14px;
