mv19amh.css:
& [data-projects] {
  display: grid;
  gap: var(--space-xxl);
  margin-block-start: var(--space-xl);
}

& [data-project] {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 24rem), 1fr));
  gap: var(--space-xl);
  align-items: center;
  scroll-margin-block-start: calc(var(--header-height) + var(--space-m));
}

/* zig-zag on wide screens only; on phones every case study is screenshot first, then the story */
@media (width > 900px) {
  & [data-project]:nth-child(even) > figure {
    order: 2;
  }
}

& figure {
  border-radius: var(--radius);
  overflow: hidden;
  border: var(--border);
  background-color: var(--bg-light);
  box-shadow: 0 30px 60px -36px color-mix(in oklch, var(--base) 45%, transparent);

  & figcaption {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 0.6em 0.9em;
    border-block-end: var(--border);
    font-size: var(--text-xs);
    color: var(--text-dark-muted);

    &::before {
      content: "";
      inline-size: 8px;
      aspect-ratio: 1;
      border-radius: 50%;
      background-color: var(--neutral-ultra-light);
      box-shadow: 12px 0 0 var(--neutral-ultra-light), 24px 0 0 var(--neutral-ultra-light);
      margin-inline-end: 30px;
    }
  }

  & img {
    display: block;
    inline-size: 100%;
    aspect-ratio: 4 / 3;
    object-fit: cover;
    object-position: top;
  }
}

& figure + div {
  display: grid;
  gap: var(--space-s);
  justify-items: start;

  & > p:first-child {
    font-size: var(--text-xs);
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--primary);
  }

  & h3 {
    font-size: var(--h3);
  }

  & h3 + p {
    font-size: var(--text-l);
    color: var(--text-dark-muted);
  }

  & dl {
    display: grid;
    gap: var(--space-xs);
    margin: 0;

    & dt {
      font-size: var(--text-xs);
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--text-dark-muted);
    }

    & dd {
      margin: 0 0 var(--space-xs);
    }
  }

  & dl + div {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-s) var(--space-m);

    & a:last-child {
      font-weight: 700;
      min-block-size: 44px;
      display: inline-flex;
      align-items: center;
    }
  }
}

& [data-tiles] {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 22rem), 1fr));
  gap: var(--grid-gap);
  margin-block-start: var(--space-xxl);

  & > * {
    display: grid;
    gap: var(--space-xs);
    align-content: start;
    padding: var(--space-l);
    border: var(--border);
    border-radius: calc(var(--radius) * 1.25);
    background-color: var(--bg-light);
    color: var(--text-dark);
    text-decoration: none;
  }

  & > * > p:first-child {
    font-size: var(--text-xs);
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--primary);
  }

  & h3 {
    font-size: var(--h4);
  }

  & p + h3 + p {
    color: var(--text-dark-muted);
  }

  & [data-go] {
    font-weight: 800;
    color: var(--primary);
  }
}

/* Tall screenshots pan top to bottom on hover (mouse only; decorative) */
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  & figure img {
    transition: object-position 1.2s cubic-bezier(.22, 1, .36, 1);
  }

  & figure:hover img {
    object-position: bottom;
    transition-duration: 7s;
    transition-timing-function: linear;
  }
}

/* ===== Mockup v117 parity ===== */
& [data-work-filter] {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-block-start: 32px;

  & button {
    all: unset;
    box-sizing: border-box;
    cursor: pointer;
    padding: 7px 14px;
    border-radius: 99px;
    border: 1.5px solid var(--neutral-ultra-light);
    font-weight: 700;
    font-size: 0.9rem;
    line-height: 1.2;
    transition: background-color 0.4s var(--ease), color 0.4s var(--ease), border-color 0.4s;

    &:hover {
      border-color: var(--primary);
      color: var(--primary);
    }

    &[aria-pressed="true"] {
      background: var(--base);
      border-color: var(--base);
      color: var(--white);
    }

    &:focus-visible {
      outline: 3px solid var(--primary);
      outline-offset: 2px;
    }
  }
}

& [data-project] {
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: clamp(28px, 4vw, 64px);

  @media (width <= 900px) {
    grid-template-columns: 1fr;
  }
}

/* screenshots in a browser frame; hover or tap scrolls the full page */
& figure {
  position: relative;
  cursor: pointer;
  border-radius: 14px 14px 6px 6px;
  border: 1px solid var(--neutral-ultra-light);
  background-color: var(--grey);
  transition: transform 0.5s var(--ease), box-shadow 0.5s var(--ease);

  &:hover {
    transform: translateY(-6px) rotate(-0.4deg);
    box-shadow: 0 40px 70px -34px color-mix(in oklch, var(--base) 50%, transparent);
  }

  &:focus-visible {
    outline: 3px solid var(--primary);
    outline-offset: 4px;
  }

  & figcaption {
    gap: 6px;
    padding: 10px 12px;
    background-color: var(--white);
    border-block-end: 1px solid var(--neutral-ultra-light);
    font-size: 0.78rem;

    &::before {
      inline-size: 9px;
      background-color: var(--grey-2);
      box-shadow: 15px 0 0 var(--grey-2), 30px 0 0 var(--grey-2);
    }
  }

  /* screenshots sit square inside the browser frame; only the frame is rounded */
  & img {
    aspect-ratio: 16 / 11;
    border-radius: 0;
  }

  &.go img {
    object-position: bottom;
    transition: object-position 7s linear;
  }

  & .ws-hint {
    position: absolute;
    inset-inline-start: 50%;
    inset-block-end: 14px;
    translate: -50% 0;
    padding: 7px 14px;
    border-radius: 99px;
    background: color-mix(in oklch, var(--base) 82%, transparent);
    color: var(--white);
    font-size: 0.8rem;
    font-weight: 700;
    white-space: nowrap;
    pointer-events: none;
    transition: opacity 0.4s var(--ease);
  }

  &:hover .ws-hint,
  &.go .ws-hint {
    opacity: 0;
  }

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }
}

& figure + div h3 {
  font-size: clamp(1.7rem, 3vw, 2.4rem);
  letter-spacing: -0.03em;
  line-height: 1;
}

/* the need / what we did / what it created: label beside answer, ruled rows */
& figure + div dl {
  grid-template-columns: 128px 1fr;
  column-gap: 12px;
  row-gap: 0;
  margin-block-start: 6px;
  border-block-start: 1px solid var(--neutral-ultra-light);

  & dt,
  & dd {
    padding-block: 12px;
    border-block-end: 1px solid var(--neutral-ultra-light);
  }

  & dt {
    font-size: 0.8rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    padding-block-start: 14px;
  }

  & dd {
    margin: 0;
    font-size: 0.96rem;
    line-height: 1.5;
  }

  @media (width <= 900px) {
    grid-template-columns: 1fr;

    & dt {
      border-block-end: 0;
      padding-block-end: 2px;
    }

    & dd {
      padding-block-start: 0;
    }
  }
}

& [data-quote] {
  /* A client's words inside a case study (set in the project's Testimonial fields; shows only when filled) */
  --blockquote-background: transparent;
  --blockquote-padding: 0;
  --blockquote-border-width: 0;
  display: grid;
  gap: var(--space-s);
  margin-block-start: var(--space-xs);
  padding: var(--space-m);
  border: 1px solid var(--neutral-ultra-light);
  border-radius: calc(var(--radius) * 1.25);
  background-color: var(--white);

  & blockquote {
    margin: 0;
    padding: 0;
    border: 0;

    & p {
      font-size: var(--text-m);
      line-height: 1.55;
      color: var(--text-dark);
    }
  }

  & > p {
    font-size: var(--text-s);
    color: var(--text-dark-muted);

    & cite {
      font-style: normal;
      font-weight: 700;
      color: var(--text-dark);
    }
  }
}


/* A tile on hold (e.g. a site still in development) stays in the builder but is never shown. Remove data-hold to bring it back. */
& [data-hold] {
  display: none;
}

