pointer-events: none;
z-index: 50;
padding: 0;

> * {
  pointer-events: auto;
}

/* # HEADER */
/* ## Overlay & Sticky Header */

&[data-overlay-header='true'],
  &[data-sticky-header='true'] {
  inset-block-start: var(--wp-admin--admin-bar--height, 0px);
}

&[data-overlay-header='true'] {
  position: absolute;
}

&[data-sticky-header='true'] {
  position: sticky;
}

&[data-sticky-header='true'][data-overlay-header='true'] {
  position: fixed;
}

&[data-overlay-header='true'][data-overlay-header-offset='true'] + main > :first-child > :first-child {
  margin-block-start: var(--header-height);
}

/* ### hide on scroll */

&[data-hide-on-scroll='true'] .header {
  transition: transform 0.4s var(--ease-swift);
}

/* ### if hiding the header move the header up on scroll */

&.hide .header {
  transform: translateY(-100%);
}

&:has(.menu-wrapper.mobile) {
  .toggle {
    display: flex;
    z-index: 1000;
  }
}

/* ## Skip Link */

.skip-link {
  position: absolute;
  top: -1500px;
  left: 32px;
  overflow: hidden;
  z-index: 999;
  background: white;
  color: black;
  border: none;

  &:focus-visible {
    top: 32px;
  }
}

/* # VARIABLES */
/* ## Link Vars */
--link-color: var(--text-color-dark);
--link-color-hover: var(--text-dark);
--link-color-active: var(--link-color-hover);
--link-bg-color: transparent;
--link-bg-color-hover: var(--bg-light);
--link-bg-color-active: var(--link-bg-color-hover);
--link-font-weight: var(--btn-font-weight);
--link-transition: all 0.2s ease-out;
--link-padding-inline: var(--btn-padding-inline);
--link-padding-block: var(--btn-padding-block);
--link-border-radius: var(--btn-border-radius);

/* ## Dropdown Vars */
--dropdown-padding: var(--space-s);
--dropdown-border-radius: var(--radius);
--dropdown-border-width: 0px;
--dropdown-border-color: var(--border-color-dark);
--dropdown-bg: white;
--dropdown-box-shadow: 0px 1px 1px rgba(3, 7, 18, 0.01), 0px 2px 3px rgba(3, 7, 18, 0.01), 0px 5px 6px rgba(3, 7, 18, 0.01), 0px 8px 11px rgba(3, 7, 18, 0.02), 0px 13px 18px rgba(3, 7, 18, 0.03), 0px 18px 25px rgba(3, 7, 18, 0.03), 0px 25px 34px rgba(3, 7, 18, 0.04), 0px 32px 45px rgba(3, 7, 18, 0.04);
--dropdown-link-min-border-radius: 8px;
--dropdown-link-padding-block: 0.75em;
--dropdown-link-padding-inline: 0.75em;
--dropdown-link-font-weight: var(--link-font-weight);
--dropdown-link-color: var(--link-color);
--dropdown-link-color-hover: var(--link-color-hover);
--dropdown-link-color-active: var(--link-color-active);
--dropdown-link-bg-color: var(--link-bg-color);
--dropdown-link-bg-color-hover: var(--link-bg-color-hover);
--dropdown-link-bg-color-active: var(--link-bg-color-active);

/* ### available dropdown vars
  --dropdown-transition-property
  --dropdown-transition-duration
  --dropdown-transition-delay
  --dropdown-transition-timing
  */
/* ### starting position for dropdown when closed on desktop (closed)*/
--dropdown-closed-top: calc(var(--space-m) + 20px);

/* ### ending position for dropdown when open on desktop (open)*/
--dropdown-open-top: calc(var(--space-m) + 20px);

/* ## Mobile Vars */
--mobile-menu-padding-inline: var(--gutter);
--mobile-menu-padding-block: var(--space-m);
--mobile-menu-bg-color: var(--white);
--mobile-menu-width: 768px;
--mobile-dropdown-stacked-timing: cubic-bezier(0.86, 0.01, 0.09, 1.01);

/* # DROPDOWN SETTINGS */
/* ## Global Dropdown Animation (Closed) */

.menu-dropdown .menu-dropdown__content-wrapper {
  filter: blur(4px);
}

/* ## Global Dropdown Animation (Open) */

.menu-dropdown.is-open > .menu-dropdown__content-wrapper {
  filter: blur(0);
}

/* ## Desktop Dropdown Animation (Closed) */

.menu-wrapper.desktop .menu-dropdown .menu-dropdown__content-wrapper,
  .menu-wrapper.desktop .morph-container {
  scale: 0.95;
}

/* ## Desktop Dropdown Animation (Open) */

.menu-wrapper.desktop .menu-dropdown.is-open > .menu-dropdown__content-wrapper,
  .menu-wrapper.desktop .morph-container.is-active {
  scale: 1;
}

/* ## Dropdown Back Button */

.menu-dropdown-back-button {
  font-weight: var(--link-font-weight);
  padding-block: 1em;
  padding-inline: var(--mobile-menu-padding-inline);
  color: var(--link-color);
  background-color: var(--mobile-menu-bg-color);
  border-block-end: 1px solid #ececec;
}

/* # ON DESKTOP */

.menu-wrapper.desktop {
  /* ## Top Level Links */

  .nav__list > li > *:is(a, button) {
    color: var(--link-color);
    text-decoration: none;
    line-height: 100%;
    border-radius: var(--link-border-radius);
    transition: var(--link-transition);
    padding-inline: var(--link-padding-inline);
    padding-block: var(--link-padding-block);
    font-weight: var(--link-font-weight);

    &:hover,
      &.active {
      background-color: var(--link-bg-color-hover);
      color: var(--link-color-hover);
    }

    &.active-link {
      color: var(--link-color-active);
      background: var(--link-bg-color-active);
    }
  }

  /* ## Last Top Level Item as Button (uncomment if wanted)
    .nav__list > li:last-child > *:is(a, button) {
      --btn-background: var(--primary);
      --btn-background-hover: var(--primary-hover);
      --btn-text-color: var(--primary-ultra-light);
      --btn-text-color-hover: var(--primary-ultra-light);
      --btn-border-color: var(--primary);
      --btn-border-color-hover: var(--primary-hover);
      --btn-outline-background-hover: var(--primary-hover);
      --btn-outline-border-hover: var(--primary-hover);
      --btn-outline-text-color: var(--primary);
      --btn-outline-text-color-hover: var(--primary-ultra-light);
      --focus-color: var(--primary-dark);
      padding-block: var(--btn-padding-block);
      padding-inline: var(--btn-padding-inline);
      min-inline-size: var(--btn-min-width);
      line-height: var(--btn-line-height);
      font-size: var(--btn-font-size, var(--text-m));
      font-weight: var(--btn-font-weight);
      font-style: var(--btn-font-style);
      text-decoration: var(--btn-text-decoration);
      text-transform: var(--btn-text-transform);
      letter-spacing: var(--btn-letter-spacing);
      border-width: var(--btn-border-width);
      border-style: var(--btn-border-style);
      border-radius: var(--btn-border-radius);
      display: var(--btn-display, inline-flex);
      text-align: center;
      justify-content: center;
      align-items: center;
      background: var(--btn-background);
      color: var(--btn-text-color);
      border-color: var(--btn-border-color);
      transition: var(--btn-transition, var(--transition));

      &:hover, &:focus-visible {
        background: var(--btn-background-hover);
        border-color: var(--btn-border-color-hover);
        color: var(--btn-text-color-hover);
        text-decoration: var(--btn-text-decoration-hover);
      }
    }
    */
  /* ## Direct List Items */

  .nav__list > li {
    inline-size: fit-content;
  }

  /* ## Links Inside Standard Dropdown */

  .menu-dropdown__content > li > *:is(a, button) {
    text-decoration: none;
    line-height: 100%;
    padding-block: var(--dropdown-link-padding-block);
    padding-inline: var(--dropdown-link-padding-inline);
    color: var(--dropdown-link-color);
    background-color: var(--dropdown-link-bg-color);
    border-radius: max(calc(var(--dropdown-border-radius) - var(--dropdown-padding)), var(--dropdown-link-min-border-radius));
    transition: var(--link-transition);
    white-space: nowrap;
    font-weight: var(--dropdown-link-font-weight);

    &:hover,
      &.active {
      background-color: var(--dropdown-link-bg-color-hover);
      color: var(--dropdown-link-color-hover);
    }

    &.active-link {
      color: var(--dropdown-link-color-active);
      background: var(--dropdown-link-bg-color-active);
    }
  }
}

/* # ON MOBILE */

.menu-wrapper.mobile {
  /* ## Top Level & Dropdown Links */

  .nav__list > li > *:is(a, button),
    .menu-dropdown__content > li > *:is(a, button) {
    color: var(--link-color);
    text-decoration: none;
    line-height: 100%;
    font-weight: var(--btn-font-weight);
    padding-block: var(--btn-padding-block);
    background-color: var(--link-bg-color);
    transition: var(--link-transition);
    padding-inline: 0;
  }

  .menu-wrapper__inner {
    display: flex;
    flex-direction: column;
  }

  .nav {
    flex: 1;
    position: relative;
    padding-inline: var(--mobile-menu-padding-inline);
    overflow-y: auto;
    overflow-x: clip;
  }

  .nav__list {
    flex-direction: column;
    flex-grow: 1;
    block-size: 100%;

    > li {
      inline-size: 100%;
      max-inline-size: 100%;

      > a,
        .menu-dropdown,
        .menu-dropdown__trigger {
        inline-size: 100%;
      }
    }
  }

  .menu-dropdown__trigger {
    inline-size: 100%;
    justify-content: space-between;
  }

  /* ## Spacing Refinements */

  :where(& .menu-dropdown__content-wrapper.stacked-mode .menu-dropdown__content) {
    padding-block: var(--mobile-menu-padding-block);
    padding-inline: var(--mobile-menu-padding-inline);
  }

  :where(& .menu-dropdown.accordion-mode .menu-dropdown__content) {
    padding-inline: var(--space-xs);
  }

  :where(& .menu-dropdown.accordion-mode[data-mega-menu='true'] .menu-dropdown__content) {
    padding-block: var(--space-xs);
  }
}

/* # TWOELEVEN THEME (ACSS tokens) */
--link-color: var(--text-light-muted);
--link-color-hover: var(--white);
--link-color-active: var(--secondary);
--link-bg-color-hover: transparent;
--link-bg-color-active: transparent;
--link-font-weight: 600;
--link-padding-inline: 0.8em;
--link-padding-block: 0;
--mobile-menu-bg-color: var(--bg-dark);
--dropdown-bg: var(--bg-dark);
--toggle-icon-color: var(--white);
--toggle-icon-size: 1.5em;

.nav__list > li > :is(a, button) {
  display: inline-flex;
  align-items: center;
  min-block-size: 44px;
  font-size: var(--text-s);
}

[data-nav-quiz] {
  --link-color: var(--tertiary);
  --link-color-hover: var(--white);
}

[data-nav-quiz] button {
  text-decoration: none;
}

[data-header-actions] {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  margin-inline-start: var(--space-s);
}

.toggle {
  min-inline-size: 44px;
  min-block-size: 44px;
  justify-content: center;
  color: var(--white);
}

/* nav labels never wrap; the menu collapses to the phone menu before they would */

& .nav :is(a, button) {
  white-space: nowrap;
}

/* ===== Mockup v117 header (bar, links, phone menu) ===== */

& .header {
  padding-block: 0;
}

& .header__container {
  min-block-size: 4rem;
}

& .header__logo {
  flex-shrink: 0;
}

& .header__logo svg {
  block-size: 30px;
  inline-size: auto;
  max-inline-size: none;

  @media (width <= 480px) {
    block-size: min(26px, calc((100vw - 2 * var(--gutter) - 64px) / 8.8)); /* phones: the bar is just the logo and the menu button, so the logo takes the room (the 8.8 is its width-to-height ratio) */
  }
}

/* desktop: nav centred between logo and button; links 22px apart; butter underline grows on hover and on the current page */

& .header__container:has(.menu-wrapper.desktop) [data-header-actions] {
  margin-inline-start: 0;
}

& .header__container:has(.menu-wrapper.mobile) {
  column-gap: 10px;

  & [data-header-actions] {
    margin-inline: auto 0;
  }
}

& .menu-wrapper.desktop {
  --link-padding-inline: 0;
  margin-inline: auto;

  & .nav__list > [data-nav-quiz] > button {
    text-decoration: none;
  }

  & .nav__list {
    gap: 22px;
  }

  & .nav__list > li > :is(a, button) {
    font-size: 0.94rem;
  }

  & .nav__list > li > a {
    position: relative;

    &::after {
      content: "";
      position: absolute;
      inset-inline: 0;
      inset-block-end: 5px;
      block-size: 2px;
      border-radius: 2px;
      background: var(--secondary);
      transform: scaleX(0);
      transform-origin: right center;
      transition: transform 0.45s var(--ease);
    }

    &:hover {
      color: var(--white);
    }

    &:hover::after,
    &[aria-current="page"]::after {
      transform: scaleX(1);
      transform-origin: left center;
    }
  }
}

/* the bar's booking button: "Free review" on small phones */

& [data-header-actions] a {
  min-inline-size: 0;
  min-block-size: 42px;
  padding-block: 0;
  padding-inline: 20px;
  font-size: 15px;
  white-space: nowrap;

  @media (width <= 860px) {
    min-block-size: 38px;
    padding-inline: 14px;
  }
}

& [data-short] {
  display: none;
}

@media (width <= 480px) {
  & [data-long] {
    display: none;
  }

  & [data-short] {
    display: inline;
  }
}

/* menu button: bordered square */

& .toggle {
  inline-size: 42px;
  block-size: 42px;
  min-inline-size: 0;
  min-block-size: 0;
  border: 1px solid var(--ink-line);
  border-radius: 12px;

  @media (width <= 760px) {
    inline-size: 40px;
    block-size: 40px;
  }
}

/* phone/tablet menu: drops under the bar; the bar (logo, booking button, close) stays visible */

& .menu-wrapper.mobile.reveal-mode {
  background-color: var(--base);
  border-block-start: 1px solid var(--ink-line);

  & .menu-wrapper__inner {
    max-block-size: none;
  }

  & .nav {
    padding: 8px var(--gutter) 18px;
  }

  & .nav__list {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  & .nav__list > li > :is(a, button) {
    display: block;
    inline-size: 100%;
    padding: 12px 0;
    font-size: 1.05rem;
    font-weight: 600;
    text-align: start;
    color: var(--white);
    border-block-end: 1px solid var(--ink-line);
  }

  & .nav__list > li > a[aria-current="page"] {
    color: var(--secondary);
  }

  & .nav__list > [data-nav-quiz] > button {
    color: var(--tertiary);
    border-block-end: 0;
    text-decoration: none;
  }

  /* the booking link only shows in the full-screen phone menu (the bar has its own button above 900px) */

  & [data-menu-hide="desktop"] {
    display: none;
  }
}

/* Phone menu: a quiet note that the Spanish site is on its way (not a link) */
& .nav__list > [data-nav-soon] {
  padding-block: var(--space-s);
  font-size: var(--text-s);
  color: var(--primary-ultra-light);
}

@media (width <= 900px) {
  & .menu-wrapper.mobile.reveal-mode.open {
    block-size: calc(100dvh - var(--header-height));
    animation: te-menu-in 0.45s var(--ease) both;
  }

  & .menu-wrapper.mobile.reveal-mode {
    & .menu-wrapper__inner {
      block-size: 100%;
      overflow-y: auto;
      overscroll-behavior: contain;
    }

    & .nav {
      block-size: 100%;
      padding: clamp(20px, 5vh, 40px) clamp(20px, 6vw, 44px) calc(28px + env(safe-area-inset-bottom, 0px));
    }

    & .nav__list {
      min-block-size: 100%;
    }

    & .nav__list > li > :is(a, button) {
      padding: 14px 0;
      font-size: clamp(1.7rem, 7.5vw, 2.4rem);
      font-weight: 800;
      letter-spacing: -0.025em;
      line-height: 1.1;
    }

    & [data-menu-hide="desktop"] {
      display: block;
      margin-block-start: auto;
      padding-block-start: var(--space-m);
    }

    & .nav__list > [data-menu-hide="desktop"] > a {
      display: flex;
      justify-content: center;
      padding: 14px 24px;
      border: 0;
      border-radius: 99px;
      background: var(--secondary);
      color: var(--base);
      font-size: 1rem;
      letter-spacing: 0;
    }
  }

  & .menu-wrapper.mobile.reveal-mode.open .nav__list > li {
    animation: te-menu-item 0.5s var(--ease) both;

    @media (prefers-reduced-motion: reduce) {
      animation: none;
    }
  }

  & .menu-wrapper.mobile.reveal-mode.open .nav__list > li:nth-child(2) {
    animation-delay: 105ms;
  }

  & .menu-wrapper.mobile.reveal-mode.open .nav__list > li:nth-child(3) {
    animation-delay: 150ms;
  }

  & .menu-wrapper.mobile.reveal-mode.open .nav__list > li:nth-child(4) {
    animation-delay: 195ms;
  }

  & .menu-wrapper.mobile.reveal-mode.open .nav__list > li:nth-child(5) {
    animation-delay: 240ms;
  }

  & .menu-wrapper.mobile.reveal-mode.open .nav__list > li:nth-child(6) {
    animation-delay: 285ms;
  }

  & .menu-wrapper.mobile.reveal-mode.open .nav__list > li:nth-child(7) {
    animation-delay: 330ms;
  }
}


/* desktop: a wider bar than the page column, with a little more room between links */
@media (width >= 64em) {
  & .header__container {
    inline-size: min(100%, 80rem);
    max-inline-size: none;
  }

  & .menu-wrapper.desktop .nav__list {
    gap: 28px;
  }
}

/* Phone and tablet bar: just the logo and the menu button (booking lives in the round button's menu and in the phone menu) */
& .header__container:has(.menu-wrapper.mobile) [data-header-actions] > a {
  display: none;
}

/* The open phone menu sits above the round quick-menu button and its booking pill (z 55 and 56) */
&:has(.menu-wrapper.open) {
  z-index: 60;
}

nlband01.css:
/* Newsletter band (component): one quiet email sign-up per page, placed after the Book band. Its button opens the shared newsletter dialog. */
--_nl-surface: var(--bg-light);
background-color: var(--_nl-surface);
color: var(--text-dark);

&[data-surface='ultra-light'] {
  --_nl-surface: var(--bg-ultra-light);
}

&[data-surface='white'] {
  --_nl-surface: var(--white);
}

& .newsletter-band__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-m) var(--space-xl);
}

& .newsletter-band__copy {
  display: grid;
  gap: var(--space-xs);
  flex: 1 1 22rem;
  max-inline-size: 34rem;
}

& .newsletter-band__kicker {
  font-size: var(--text-xs);
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--primary);
}

& .newsletter-band__title {
  font-size: var(--h3);
  font-weight: 800;
  line-height: var(--heading-line-height);
  text-wrap: balance;
}

& .newsletter-band__sub {
  color: var(--text-dark-muted);
  max-inline-size: 52ch;
  text-wrap: pretty;
}

& .newsletter-band__row > .btn--outline {
  flex: none;
}

nldlg001.css:
/* Newsletter sign-up dialog (global, lives in the footer). Full screen on phones; the close button is a round icon button. */
margin: auto;
inline-size: min(36rem, calc(100vw - 20px));
max-block-size: calc(100dvh - 24px);
padding: 0;
border: 0;
border-radius: calc(var(--radius) * 1.5);
background-color: var(--bg-light);
color: var(--text-dark);
overflow: auto;
overscroll-behavior: contain;

&::backdrop {
  background: color-mix(in oklch, var(--base) 62%, transparent);
}

/* the close button and the content share one grid cell, so the button never narrows the content */
&[open] {
  display: grid;
  grid-template: "stack" auto / minmax(0, 1fr);
}

& [data-newsletter-close] {
  grid-area: stack;
  justify-self: end;
  align-self: start;
  position: sticky;
  inset-block-start: 12px;
  z-index: 2;
  margin: 12px 12px 0 0;
}

& > div {
  grid-area: stack;
  min-inline-size: 0;
  padding: clamp(26px, 4vw, 40px);
}

/* the shared sign-up card, laid open: the dialog is the card */
& .insights-signup {
  max-inline-size: none;
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
}

& .insights-signup .insights-signup__title {
  font-size: var(--h3);
}

@media (width <= 760px) {
  inline-size: 100vw;
  max-inline-size: 100vw;
  block-size: 100dvh;
  max-block-size: 100dvh;
  margin: 0;
  inset: 0;
  border-radius: 0;

  & > div {
    padding: var(--space-xl) var(--gutter);
  }
}

nlfoot01.css:
/* Footer newsletter row: compact, every page, the first thing in the footer. Its button opens the shared newsletter dialog. */
display: flex;
flex-direction: row;
flex-wrap: wrap;
align-items: center;
justify-content: space-between;
gap: var(--space-s) var(--space-l);
inline-size: 100%;
max-inline-size: var(--content-width);
margin-inline: auto;
padding: var(--space-xl) 0 var(--space-l);
border-block-end: var(--border-light);

& .site-footer__newsletter-copy {
  display: grid;
  gap: var(--space-3xs);
  flex: 1 1 16rem;
}

& .site-footer__newsletter-label {
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--white);
}

& .site-footer__newsletter-title {
  max-inline-size: 40ch;
  font-size: var(--text-l);
  font-weight: 700;
  line-height: 1.25;
