&.quote-band--long figcaption {
  display: block;
}

& figcaption cite {
  font-style: normal;
  font-weight: 800;
  color: var(--white);
}

reach01.css:
/* Home: "Who you can reach" (front door). Three people, one website: pick a person, the search types
   what they look for, the lines draw to the site and the browser shows the page they land on.
   Native scroll only (no pin or sticky). Reduced motion shows the final state. Built from the chosen prototype (direction D). */
container-type: inline-size;

& > [data-etch-element="container"] {
  display: grid;
  gap: var(--space-l);

  & > * {
    min-inline-size: 0;
  }
}

& h2 {
  margin: 8px 0 0;
  font-size: clamp(32px, 8.4cqi, 56px);
  line-height: 0.99;
  letter-spacing: -0.03em;
  font-weight: 800;
  text-wrap: balance;
  max-inline-size: 16ch;
  color: var(--base);
}

& .hl {
  color: var(--primary);
}

& .reach-lead {
  margin: 14px 0 0;
  font-size: 17px;
  line-height: 1.55;
  color: var(--text-dark-muted);
  max-inline-size: 44ch;
}

& .tag {
  display: inline-flex;
  align-items: center;
  block-size: 22px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
  margin-block-start: 3px;
}

& .t-reach {
  background-color: var(--primary);
  color: var(--white);
}

& .t-mob {
  background-color: var(--base);
  color: var(--primary-light);
}

& .t-fund {
  background-color: var(--secondary);
  color: var(--base);
  border: 1px solid var(--secondary-light);
}

& .when {
  font-size: 11px;
  letter-spacing: 0.08em;
  line-height: 1.35;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--text-dark-muted);
  white-space: nowrap;
}

/* Reveal */
& .rv {
  transition: opacity 0.6s var(--ease), transform 0.6s var(--ease);
}

&.is-armed .rv:not(.in) {
  opacity: 0;
  transform: translateY(18px);
}

/* People (tabs) */
& .d-hint {
  margin: -4px 0 6px;
  text-align: center;
  font-size: 13px;
  color: var(--text-dark-muted);
}

& .f-people {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

& .f-p {
  display: grid;
  gap: 3px;
  justify-items: center;
  text-align: center;
  background: transparent;
  border: 1px solid var(--neutral-ultra-light);
  border-radius: 14px;
  padding: 10px 4px 12px;
  color: var(--base);
  font: inherit;
  cursor: pointer;
  transition: background-color 0.3s, border-color 0.3s, box-shadow 0.3s;

  & b {
    font-size: 16px;
    line-height: 1.15;
    white-space: nowrap;
  }

  &[aria-selected="true"] {
    background-color: var(--white);
    border-color: var(--base);
    box-shadow: 0 10px 24px -18px color-mix(in oklch, var(--base) 50%, transparent);
  }

  &:focus-visible {
    outline: 3px solid var(--primary);
    outline-offset: 3px;
  }
}

/* What they search for */
& .f-q {
  display: grid;
  gap: 6px;
  justify-items: center;
  margin-block-start: 10px;
}

& .f-ql {
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--text-dark-muted);
}

& .f-qbar {
  display: flex;
  align-items: center;
  gap: 10px;
  inline-size: 100%;
  max-inline-size: 460px;
  min-block-size: 48px;
  background-color: var(--white);
  border: 1px solid var(--neutral-ultra-light);
  border-radius: 999px;
  padding: 10px 18px;
  font-size: 16px;
  line-height: 1.3;
  color: var(--base);
  box-shadow: 0 10px 24px -20px color-mix(in oklch, var(--base) 50%, transparent);

  & svg {
    flex: none;
  }
}

& .caret::after {
  content: "";
  display: inline-block;
  inline-size: 1px;
  block-size: 12px;
  background-color: var(--primary);
  margin-inline-start: 1px;
  vertical-align: -2px;
  animation: reach-blink 1s steps(1) infinite;
}

@keyframes reach-blink {
  50% {
    opacity: 0;
  }
}

& .f-gloss {
  font-size: 13px;
  line-height: 20px;
  color: var(--text-dark-muted);
  min-block-size: 20px;
}

/* The three lines converge on the site */
& .d-lines {
  display: block;
  inline-size: 100%;
  block-size: 56px;
  margin: -2px 0 -6px;

  & path {
    fill: none;
    stroke: var(--neutral-ultra-light);
    stroke-width: 2;
    vector-effect: non-scaling-stroke;
  }

  & .go {
    stroke: var(--primary);
    stroke-width: 3;
    stroke-dasharray: 2000;
    stroke-dashoffset: 2000;
    transition: stroke-dashoffset 0.9s var(--ease), opacity 0.3s;
  }

  & .go:nth-of-type(5) {
    transition-delay: 0.15s;
  }

  & .go:nth-of-type(6) {
    transition-delay: 0.3s;
  }
}

& .d-door.in .d-lines .go {
  stroke-dashoffset: 0;
}

& .d-door[data-focus] .go {
  opacity: 0.15;
}

& .d-door[data-focus="0"] .go[data-i="0"],
& .d-door[data-focus="1"] .go[data-i="1"],
& .d-door[data-focus="2"] .go[data-i="2"] {
  opacity: 1;
}

/* The one website */
& .frame {
  background-color: var(--white);
  border: 1px solid var(--neutral-ultra-light);
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 18px 40px -28px color-mix(in oklch, var(--base) 35%, transparent);
}

& .bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-block-end: 1px solid var(--neutral-ultra-light);
  background-color: color-mix(in oklch, var(--neutral-ultra-light) 30%, var(--white));

  & i {
    inline-size: 8px;
    block-size: 8px;
    border-radius: 50%;
    background-color: var(--neutral-ultra-light);
    display: block;
  }
}

& .url {
  flex: 1;
  text-align: center;
  font-size: 12px;
  color: var(--text-dark-muted);
  background-color: var(--white);
  border: 1px solid var(--neutral-ultra-light);
  border-radius: 999px;
  padding: 3px 10px;
}

& .lang {
  font-size: 11px;
  font-weight: 700;
  border: 1px solid var(--neutral-ultra-light);
  border-radius: 999px;
  padding: 2px 8px;
  color: var(--text-dark-muted);
}

& .f-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px 0;
  font-size: 13px;
  font-weight: 800;
  color: var(--base);
}

& .f-doors {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 10px 16px 12px;
  border-block-end: 1px solid var(--neutral-ultra-light);

  & span {
    font-size: 12px;
    font-weight: 700;
    border: 1px solid var(--neutral-ultra-light);
    border-radius: 999px;
    padding: 4px 10px;
    color: var(--text-dark-muted);
    transition: background-color 0.3s, color 0.3s, border-color 0.3s;
  }
}

& .d-door[data-focus="0"] .f-doors [data-i="0"],
& .d-door[data-focus="1"] .f-doors [data-i="1"],
& .d-door[data-focus="2"] .f-doors [data-i="2"] {
  background-color: var(--primary);
  border-color: var(--primary);
  color: var(--white);
}

& .f-screen {
  display: grid;
  padding: 16px 16px 18px;
}

& .f-page {
  grid-area: 1 / 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 14px;
  color: var(--base);
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: opacity 0.45s var(--ease), transform 0.45s var(--ease), visibility 0s 0.45s;

  &.on {
    opacity: 1;
    visibility: visible;
    transform: none;
    transition-delay: 0.05s, 0.05s, 0s;
  }
}

& .f-h {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.02em;
}

& .mp {
  margin: 0;
  color: var(--text-dark-muted);
}

& .row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border: 1px solid var(--neutral-ultra-light);
  border-radius: 10px;
  padding: 9px 10px;
  font-weight: 600;

  &::after {
    content: "›";
    color: var(--text-dark-muted);
    font-weight: 400;
  }
}

& .fld {
  border: 1px solid var(--neutral-ultra-light);
  border-radius: 10px;
  padding: 9px 10px;
  color: var(--base);
}

& .mbtn {
  margin-block-start: 6px;
  background-color: var(--primary);
  color: var(--white);
  border-radius: 999px;
  text-align: center;
  font-weight: 700;
  padding: 12px;
  font-size: 14px;

  &.pulse {
    animation: reach-pulse 1.6s var(--ease) infinite;
  }
}

@keyframes reach-pulse {
  0% {
    box-shadow: 0 0 0 0 color-mix(in oklch, var(--primary) 45%, transparent);
  }

  100% {
    box-shadow: 0 0 0 12px color-mix(in oklch, var(--primary) 0%, transparent);
  }
}

& .ok {
  background-color: var(--secondary);
  border: 1px solid var(--secondary-light);
  border-radius: 12px;
  padding: 10px;
  font-weight: 700;
  display: grid;
  gap: 2px;

  & span {
    font-weight: 400;
    color: var(--text-dark-muted);
  }
}

& .f-done {
  display: none;
}

& [data-reach-rsvp][data-done] .f-go {
  display: none;
}

& [data-reach-rsvp][data-done] .f-done {
  display: grid;
}

/* The closing line: its own moment */
& .payoff {
  display: grid;
  gap: 12px;
  padding-block-start: 0;

  & p {
    margin: 0;
    font-size: clamp(40px, 10.4cqi, 84px);
    line-height: 0.99;
    letter-spacing: -0.035em;
    font-weight: 800;
    text-wrap: balance;
    max-inline-size: 13ch;
    color: var(--base);
  }

  & .payoff-sub {
    font-size: clamp(20px, 5.2cqi, 30px);
    line-height: 1.3;
    font-weight: 600;
    letter-spacing: -0.01em;
    max-inline-size: 28ch;
    margin-block-start: -4px;
  }
}

& .mark {
  inline-size: 44px;
  block-size: 36px;

  & rect {
    transform-box: fill-box;
    transform-origin: bottom;
    transition: transform 0.6s var(--ease);
  }

  & .s2 {
    transition-delay: 0.25s;
  }
}

&.is-armed .payoff:not(.in) .mark rect {
  transform: scaleY(0);
}

@container (min-width: 760px) {
  & > [data-etch-element="container"] {
    gap: 32px;
  }

  /* one line for the headline, two for the closing line */
  & h2 {
    max-inline-size: none;
    font-size: clamp(40px, 4.4cqi, 64px);
  }

  & .payoff p {
    max-inline-size: 22ch;
    font-size: clamp(48px, 5.6cqi, 84px);
  }

  & .d-door {
    max-inline-size: 820px;
    margin-inline: auto;
    inline-size: 100%;
  }

  & .f-people {
    gap: 16px;
  }

  & .f-p {
    padding: 14px 8px 16px;

    & .when {
      font-size: 12px;
    }

    & b {
      font-size: 20px;
    }
  }

  & .d-lines {
    block-size: 64px;
  }

  & .f-frame {
    max-inline-size: 640px;
    margin-inline: auto;
    inline-size: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  & *,
  & *::before,
  & *::after {
    transition: none !important;
    animation: none !important;
  }

  & .d-lines .go {
    stroke-dashoffset: 0;
  }
}

